"use client";

import type { ComponentProps } from "react";

import { Shutter } from "@/components/shutter";

/** 3D curvature with thick slats. Color: Industrial. */
export function ShutterCurvedThickIndustrial(props: ComponentProps<typeof Shutter>) {
  return (
    <Shutter
      size="md"
      slatSize="thick"
      curved
      defaultLevel={55}
      variant="industrial"
      label="Curved thick · Industrial"
      {...props}
    />
  );
}
